-- Public snapshot: owner@example.invalid is a placeholder, never an automatic grant to the original operator.
begin;
do $$ declare founder uuid; owner_id uuid:=gen_random_uuid(); player_id uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); item public.character_items; obj uuid; objects jsonb;
begin
 select id into founder from auth.users where lower(email)='owner@example.invalid';
 if public.staff_rank('unrelated-world',founder)<>4 then raise exception 'Founder not global';end if;
 insert into auth.users(id,raw_user_meta_data) values(owner_id,'{}'),(player_id,'{}');
 insert into public.worlds(id,name) values('test-founder-world','Test');
 insert into public.world_staff values('alska-mogue',owner_id,'Server Owner');
 if public.staff_rank('alska-mogue',owner_id)<>3 or public.staff_rank('test-founder-world',owner_id)<>0 then raise exception 'Owner hierarchy/scope';end if;
 perform set_config('request.jwt.claim.sub',founder::text,true);
 perform public.moderation_action(gen_random_uuid(),'test-founder-world','grant_owner',owner_id,'Test assignment');
 if public.staff_rank('test-founder-world',owner_id)<>3 then raise exception 'Owner assignment failed';end if;
 insert into public.characters(id,player_id,world_id,slot,name,room_id) values(c,player_id,'alska-mogue',1,'Pickup test','roomA');
 perform public.save_room('alska-mogue','roomA','Room A','Moon Crossing','Test','[{"name":"Full","script":"lockpick-full"},{"name":"Damaged","script":"lockpick-damaged"},{"name":"Broken","script":"lockpick-broken"},{"name":"Key","script":"room-c-key"}]',null);
 select l.objects into objects from public.world_locations l where world_id='alska-mogue' and id='roomA';
 perform set_config('request.jwt.claim.sub',player_id::text,true);
 obj:=(objects->0->>'id')::uuid;item:=public.pickup_room_object(c,obj);
 if item.capacity<>100 then raise exception 'Full capacity wrong';end if;
 if (public.pickup_room_object(c,obj)).id<>item.id then raise exception 'Retry duplicated pickup';end if;
 item:=public.pickup_room_object(c,(objects->1->>'id')::uuid);if item.capacity<>50 then raise exception 'Damage capacity wrong';end if;
 item:=public.pickup_room_object(c,(objects->2->>'id')::uuid);if item.capacity<>0 then raise exception 'Broken capacity wrong';end if;
 item:=public.pickup_room_object(c,(objects->3->>'id')::uuid);if item.kind<>'key' then raise exception 'Wrong key';end if;
 if (select jsonb_array_length(l.objects) from public.world_locations l where world_id='alska-mogue' and id='roomA')<>0 then raise exception 'Items not consumed';end if;
 perform set_config('request.jwt.claim.sub',founder::text,true);
 perform public.save_room('alska-mogue','roomA','Room A','Moon Crossing','Test',objects,null);
 if (select jsonb_array_length(l.objects) from public.world_locations l where world_id='alska-mogue' and id='roomA')<>0 then raise exception 'Stale editor respawned pickup';end if;
 perform public.save_room('alska-mogue','roomA','Room A','Moon Crossing','Test','[{"name":"Fourth","script":"lockpick-full"}]',null);
 select (l.objects->0->>'id')::uuid into obj from public.world_locations l where world_id='alska-mogue' and id='roomA';
 perform set_config('request.jwt.claim.sub',player_id::text,true);
 item:=public.pickup_room_object(c,obj);if item.capacity<>100 then raise exception 'Third usable pick unavailable';end if;
 perform set_config('request.jwt.claim.sub',founder::text,true);
 perform public.save_room('alska-mogue','roomA','Room A','Moon Crossing','Test','[{"name":"Extra","script":"lockpick-full"}]',null);
 select (l.objects->0->>'id')::uuid into obj from public.world_locations l where world_id='alska-mogue' and id='roomA';
 perform set_config('request.jwt.claim.sub',player_id::text,true);
 begin perform public.pickup_room_object(c,obj);raise exception 'Fourth usable lockpick allowed';exception when others then if sqlerrm<>'Inventory limit reached for this item' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 begin perform public.moderation_action(gen_random_uuid(),'alska-mogue','grant_owner',player_id,'Forbidden');raise exception 'Owner assigned peer';exception when others then if sqlerrm<>'Admin permission required for this world' then raise;end if;end;
 begin perform public.moderation_action(gen_random_uuid(),'alska-mogue','ban',founder,'Forbidden');raise exception 'Founder moderated';exception when others then if sqlerrm<>'You can only moderate players below your role' then raise;end if;end;
end $$;
rollback;
select 'PASS: global Founder, owner hierarchy, saved pickup capacities, retry safety, shared consumption, inventory cap' as result;
